<style>
    .sivmi-chat-shell{display:flex;width:100%;max-width:84rem;height:clamp(34rem,calc(100dvh - 13rem),50rem);min-height:34rem;margin-inline:auto;flex-direction:column;overflow:hidden;background:#fff;border:1px solid #dfe6ef;border-radius:18px;box-shadow:0 16px 44px rgb(15 23 42 / 8%)}
    .sivmi-chat-header{position:relative;z-index:2;flex:none;padding:1rem 1.25rem;background:rgb(255 255 255 / 96%);border-bottom:1px solid #e5eaf2;box-shadow:0 3px 12px rgb(15 23 42 / 3%);backdrop-filter:blur(12px)}
    .sivmi-chat-contact{display:flex;align-items:center;justify-content:space-between;gap:1rem}
    .sivmi-chat-contact-main{display:flex;min-width:0;align-items:center;gap:.8rem}
    .sivmi-chat-avatar{display:flex;width:3rem;height:3rem;flex:none;align-items:center;justify-content:center;color:#047857;font-size:.8rem;font-weight:800;letter-spacing:.025em;background:linear-gradient(145deg,#d1fae5,#a7f3d0);border:3px solid #ecfdf5;border-radius:999px;box-shadow:0 0 0 1px #a7f3d0}
    .sivmi-chat-contact-copy{min-width:0}.sivmi-chat-contact-name-row{display:flex;min-width:0;align-items:center;gap:.5rem}
    .sivmi-chat-contact-name-row h2{overflow:hidden;color:#0f172a;font-size:1rem;font-weight:700;line-height:1.35;text-overflow:ellipsis;white-space:nowrap}
    .sivmi-chat-presence{width:.5rem;height:.5rem;flex:none;border-radius:999px;box-shadow:0 0 0 3px #ecfdf5}
    .sivmi-chat-contact-meta{display:flex;min-width:0;align-items:center;gap:.35rem;margin-top:.2rem;color:#64748b;font-size:.75rem;line-height:1.25}
    .sivmi-chat-contact-meta svg{width:.82rem;height:.82rem;flex:none;color:#94a3b8}.sivmi-chat-contact-meta span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
    .sivmi-chat-badges{display:flex;flex-wrap:wrap;align-items:center;justify-content:flex-end;gap:.45rem}
    .sivmi-chat-badge{display:inline-flex;max-width:16rem;align-items:center;gap:.35rem;padding:.4rem .65rem;overflow:hidden;font-size:.7rem;font-weight:650;line-height:1;text-overflow:ellipsis;white-space:nowrap;border:1px solid transparent;border-radius:999px}
    .sivmi-chat-badge svg{width:.8rem;height:.8rem;flex:none}.sivmi-chat-badge-dot{width:.38rem;height:.38rem;flex:none;border-radius:999px}
    .sivmi-chat-badge-success{color:#047857;background:#ecfdf5;border-color:#bbf7d0}.sivmi-chat-badge-danger{color:#be123c;background:#fff1f2;border-color:#fecdd3}
    .sivmi-chat-badge-info{color:#075985;background:#f0f9ff;border-color:#bae6fd}.sivmi-chat-badge-lead{color:#7e22ce;background:#faf5ff;border-color:#e9d5ff;transition:.18s}.sivmi-chat-badge-lead:hover{background:#f3e8ff;border-color:#d8b4fe}
    .sivmi-chat-messages{min-height:0;flex:1;overflow-y:auto;overscroll-behavior:contain;padding:1.35rem 1.65rem 1.65rem;background-color:#f6f8fc;background-image:radial-gradient(circle at 1px 1px,rgb(148 163 184 / 10%) 1px,transparent 0);background-size:24px 24px;scrollbar-color:#cbd5e1 transparent;scrollbar-width:thin}
    .sivmi-chat-messages::-webkit-scrollbar{width:7px}.sivmi-chat-messages::-webkit-scrollbar-thumb{background:#cbd5e1;border-radius:999px}
    .sivmi-chat-message-list{display:flex;width:100%;max-width:64rem;min-height:100%;margin-inline:auto;flex-direction:column;gap:.9rem}
    .sivmi-chat-date-divider{display:flex;align-items:center;justify-content:center;gap:.75rem;margin:.2rem 0 .4rem;color:#64748b;font-size:.7rem;font-weight:650}
    .sivmi-chat-date-divider::before,.sivmi-chat-date-divider::after{width:min(8rem,20%);height:1px;content:'';background:#dbe3ed}.sivmi-chat-date-divider span{padding:.38rem .75rem;background:rgb(255 255 255 / 88%);border:1px solid #e2e8f0;border-radius:999px;box-shadow:0 2px 7px rgb(15 23 42 / 4%)}
    .sivmi-chat-message-row{display:flex;width:100%;align-items:flex-end;gap:.6rem}.sivmi-chat-message-row-inbound{justify-content:flex-start}.sivmi-chat-message-row-outbound{justify-content:flex-end}
    .sivmi-chat-message-avatar{display:flex;width:2rem;height:2rem;flex:none;align-items:center;justify-content:center;margin-bottom:.15rem;color:#047857;font-size:.62rem;font-weight:800;background:#fff;border:1px solid #dbe3ed;border-radius:999px;box-shadow:0 3px 8px rgb(15 23 42 / 6%)}
    .sivmi-chat-bubble{min-width:12rem;max-width:min(80%,48rem);padding:.95rem 1.05rem .75rem;overflow:hidden;border-radius:18px;box-shadow:0 6px 16px rgb(15 23 42 / 8%)}
    .sivmi-chat-bubble-inbound{color:#1e293b;background:#fff;border:1px solid #dfe6ef;border-bottom-left-radius:5px}.sivmi-chat-bubble-outbound{color:#fff;background:linear-gradient(145deg,#1476b8,#09679f);border:1px solid rgb(7 89 133 / 30%);border-bottom-right-radius:5px}
    .sivmi-chat-message-body{margin:0;overflow-wrap:anywhere;font-size:.95rem;line-height:1.6;white-space:pre-wrap}.sivmi-chat-message-time{display:flex;align-items:center;justify-content:flex-end;gap:.2rem;margin-top:.55rem;font-size:.69rem;font-weight:500;line-height:1}.sivmi-chat-message-time-inbound{color:#94a3b8}.sivmi-chat-message-time-outbound{color:#dbeafe}
    .sivmi-chat-media-link{display:block;margin:-.45rem -.55rem .1rem;overflow:hidden;border-radius:13px}.sivmi-chat-media-image,.sivmi-chat-media-video{display:block;width:100%;max-width:34rem;max-height:28rem;object-fit:contain;background:#0f172a;border-radius:13px}.sivmi-chat-media-video{min-width:min(30rem,65vw)}.sivmi-chat-message-caption{margin-top:.7rem}.sivmi-chat-media-unavailable{min-width:15rem;padding:1rem;color:#64748b;font-size:.8rem;text-align:center;background:rgb(148 163 184 / 12%);border:1px dashed #cbd5e1;border-radius:12px}.sivmi-chat-bubble-outbound .sivmi-chat-media-unavailable{color:#dbeafe;border-color:rgb(255 255 255 / 25%)}
    .sivmi-chat-empty{display:flex;max-width:23rem;min-height:22rem;margin:auto;flex-direction:column;align-items:center;justify-content:center;padding:2rem;color:#64748b;text-align:center}.sivmi-chat-empty-icon{display:flex;width:3.6rem;height:3.6rem;align-items:center;justify-content:center;color:#1476b8;background:#fff;border:1px solid #dfe6ef;border-radius:999px;box-shadow:0 8px 22px rgb(15 23 42 / 7%)}.sivmi-chat-empty-icon svg{width:1.75rem;height:1.75rem}.sivmi-chat-empty p{margin-top:1rem;color:#1e293b;font-size:.9rem;font-weight:700}.sivmi-chat-empty span{margin-top:.35rem;font-size:.78rem;line-height:1.55}
    .sivmi-chat-composer{position:relative;z-index:2;flex:none;padding:.85rem 1.25rem .75rem;background:#fff;border-top:1px solid #e5eaf2;box-shadow:0 -4px 16px rgb(15 23 42 / 3%)}.sivmi-chat-composer-inner{width:100%;max-width:64rem;margin-inline:auto}.sivmi-chat-composer-row{display:flex;align-items:flex-end;gap:.7rem}.sivmi-chat-input-wrap{min-width:0;flex:1}
    .sivmi-chat-attach{display:flex;width:3.15rem;height:3.15rem;flex:none;align-items:center;justify-content:center;color:#1476b8;background:#eff8ff;border:1px solid #bae6fd;border-radius:14px;cursor:pointer;transition:.18s}.sivmi-chat-attach:hover{color:#fff;background:#1476b8}.sivmi-chat-attach input{position:absolute;width:1px;height:1px;overflow:hidden;opacity:0}.sivmi-chat-attach svg{width:1.2rem;height:1.2rem}.sivmi-chat-attach-disabled{cursor:not-allowed;opacity:.5}.sivmi-chat-attachment-preview{display:flex;align-items:center;gap:.7rem;margin-bottom:.7rem;padding:.55rem .7rem;background:#f8fafc;border:1px solid #dbe3ed;border-radius:13px}.sivmi-chat-attachment-icon{display:flex;width:3rem;height:3rem;flex:none;align-items:center;justify-content:center;overflow:hidden;color:#1476b8;background:#e0f2fe;border-radius:10px}.sivmi-chat-attachment-icon img{width:100%;height:100%;object-fit:cover}.sivmi-chat-attachment-icon svg{width:1.4rem;height:1.4rem}.sivmi-chat-attachment-copy{display:flex;min-width:0;flex:1;flex-direction:column}.sivmi-chat-attachment-copy strong{overflow:hidden;color:#1e293b;font-size:.78rem;text-overflow:ellipsis;white-space:nowrap}.sivmi-chat-attachment-copy span{margin-top:.12rem;color:#64748b;font-size:.67rem}.sivmi-chat-attachment-remove{display:flex;width:1.8rem;height:1.8rem;align-items:center;justify-content:center;color:#64748b;font-size:1.25rem;background:#fff;border:1px solid #dbe3ed;border-radius:999px}.sivmi-chat-attachment-remove:hover{color:#e11d48;border-color:#fecdd3}.sivmi-chat-upload-progress{height:.25rem;margin-bottom:.55rem;overflow:hidden;background:#e2e8f0;border-radius:999px}.sivmi-chat-upload-progress span{display:block;height:100%;background:#1476b8;transition:width .15s}
    .sivmi-chat-input{display:block;width:100%;min-height:3.15rem;max-height:8rem;padding:.82rem .95rem;resize:vertical;color:#0f172a;font-size:.9rem;line-height:1.45;background:#f8fafc;border:1px solid #cbd5e1;border-radius:14px;outline:none;transition:.18s}.sivmi-chat-input::placeholder{color:#94a3b8}.sivmi-chat-input:focus{background:#fff;border-color:#1476b8;box-shadow:0 0 0 3px rgb(20 118 184 / 12%)}.sivmi-chat-input:disabled{cursor:not-allowed;background:#f1f5f9;opacity:.65}
    .sivmi-chat-send{display:inline-flex;height:3.15rem;flex:none;align-items:center;justify-content:center;gap:.45rem;padding-inline:1.2rem;color:#fff;font-size:.84rem;font-weight:700;background:#1476b8;border-radius:14px;box-shadow:0 7px 16px rgb(20 118 184 / 20%);transition:.18s}.sivmi-chat-send:hover{background:#075985;box-shadow:0 9px 20px rgb(7 89 133 / 24%);transform:translateY(-1px)}.sivmi-chat-send:focus{outline:none;box-shadow:0 0 0 3px rgb(20 118 184 / 20%)}.sivmi-chat-send:disabled{cursor:not-allowed;opacity:.5;transform:none}.sivmi-chat-send svg{width:1rem;height:1rem}
    .sivmi-chat-composer-help{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-top:.42rem;color:#94a3b8;font-size:.66rem;line-height:1.3}.sivmi-chat-composer-error{margin-top:.42rem;color:#e11d48;font-size:.7rem}.sivmi-chat-shortcut{flex:none}
    @media(max-width:639px){.sivmi-chat-shell{height:clamp(31rem,calc(100dvh - 10.5rem),44rem);min-height:31rem;border-radius:14px}.sivmi-chat-header{padding:.8rem .85rem}.sivmi-chat-contact{align-items:flex-start;flex-direction:column;gap:.75rem}.sivmi-chat-avatar{width:2.55rem;height:2.55rem}.sivmi-chat-badges{width:100%;flex-wrap:nowrap;justify-content:flex-start;padding-bottom:.12rem;overflow-x:auto;scrollbar-width:none}.sivmi-chat-badges::-webkit-scrollbar{display:none}.sivmi-chat-messages{padding:1rem .75rem 1.25rem}.sivmi-chat-message-list{gap:.7rem}.sivmi-chat-message-avatar{display:none}.sivmi-chat-bubble{min-width:10rem;max-width:94%;padding:.82rem .9rem .65rem}.sivmi-chat-media-video{min-width:min(22rem,72vw)}.sivmi-chat-message-body{font-size:.9rem}.sivmi-chat-composer{padding:.7rem .75rem .6rem}.sivmi-chat-composer-row{gap:.45rem}.sivmi-chat-attach,.sivmi-chat-send{width:3.15rem;padding:0}.sivmi-chat-send span{display:none}.sivmi-chat-composer-help{display:none}}
</style>
